@block QuadRotaryCtrl begin
    # 1 kHz firmware of the quadruple pendulum on the rotary arm (generated by
    # design/build_models.py from design/design_rotary.json: do not edit the tables by hand).
    #
    #   phase 0  t < t_on            hold: arm torque 0 (hanging at rest)
    #   phase 1  SWINGING UP         u = u*(tau) - K(tau) (z - z*(tau)), tau = t - t_on: the feed-forward and
    #                                time-varying LQR of the offline trajectory optimisation (looked up by
    #                                QuadRotaryTraj and sampled here: ff = u*, xs = z*, Ks = K)
    #   phase 2  BALANCING (latched) u = -Klqr z, the infinite-horizon discrete LQR at the upright
    #
    # z = [s, phi_1 .. phi_4, sd, phid_1 .. phid_4]: s the arm angle, phi_i the absolute angle of link i from
    # the upward vertical (sums of the relative joint encoder angles). The catch latches phase 2 once, when
    # tau >= t_s - 0.5 s and the LQR cost-to-go z' Pc z is below catch_tol (the catch region).
    # balance_only starts in phase 2 (the balance scenario).
    #
    # Actuator: the command is clamped to +-u_max, then slew-rate limited (slew per second) and finally
    # delayed by delay_n whole samples (0 .. 10). Sensors: with `quant` the encoders are quantised
    # (res_s, res_q) and the rates are filtered backward differences (time constant tau_f) instead of the
    # exact rates. The zero-order hold breaks the algebraic loop through the plant.
    @inputs begin
        tm::Real, [unit = "s"]
        s::Real, [unit = "rad"]
        sd::Real, [unit = "rad/s"]
        q1::Real, [unit = "rad"]
        q2::Real, [unit = "rad"]
        q3::Real, [unit = "rad"]
        q4::Real, [unit = "rad"]
        wq1::Real, [unit = "rad/s"]
        wq2::Real, [unit = "rad/s"]
        wq3::Real, [unit = "rad/s"]
        wq4::Real, [unit = "rad/s"]
        ff::Real, [unit = "N*m"]
        xs::Vec{10}
        Ks::Vec{10}
    end
    @outputs begin
        u::Real = 0.0, [unit = "N*m", description = "Applied arm torque"]
        ucmd::Real = 0.0, [unit = "N*m", description = "Controller command before the slew limit and the delay"]
        phase::Real = 0.0, [description = "0 hold, 1 swinging up (TVLQR), 2 balancing (LQR)"]
        swinging::Real = 0.0, [description = "1 while swinging up"]
        balancing::Real = 0.0, [description = "1 while balancing"]
        vcost::Real = 0.0, [description = "LQR cost-to-go of the measured state (catch region test)"]
    end
    @parameters begin
        Klqr::Vec{10} = [0.404447725164, 16.0634951475, -136.333594513, 326.222112629, -218.891070364, 0.578197117408, -0.625998238122, -1.00126152218, 9.68653342873, -12.9801733158], [description = "Balance LQR gain (u = -Klqr z)"]
        Pc::Mat{10,10} = [2908.64347 -2991.69139 -5358.84848 49174.6199 -65115.6795 2063.09739 -1057.85637 -654.059956 -316.974853 -4684.49977; -2991.69139 80150.4198 -53560.2179 -448154.567 484335.621 -3291.7327 1706.94523 -6371.43045 -7705.65283 32326.053; -5358.84848 -53560.2179 2091306.41 -5516400.95 3639150.36 -7120.28814 14676.8237 4239.19732 -171570.886 213330.248; 49174.6199 -448154.567 -5516400.95 22622568.3 -18314644.2 71718.2958 -66040.7324 55637.7526 572722.72 -1147999.76; -65115.6795 484335.621 3639150.36 -18314644.2 16175816.8 -89908.147 65040.1649 -50638.6532 -403140.889 1039300.31; 2063.09739 -3291.7327 -7120.28814 71718.2958 -89908.147 2254.38277 -1168.20372 -597.6369 -64.7661808 -6373.50219; -1057.85637 1706.94523 14676.8237 -66040.7324 65040.1649 -1168.20372 684.15964 317.209866 -901.417951 4367.68573; -654.059956 -6371.43045 4239.19732 55637.7526 -50638.6532 -597.6369 317.209866 1206.76391 1604.63814 -3172.70301; -316.974853 -7705.65283 -171570.886 572722.72 -403140.889 -64.7661808 -901.417951 1604.63814 17480.7526 -24037.5527; -4684.49977 32326.053 213330.248 -1147999.76 1039300.31 -6373.50219 4367.68573 -3172.70301 -24037.5527 67297.1161], [description = "LQR cost-to-go matrix of the catch region"]
        t_on::Real = 1.0, [unit = "s", description = "Start of the swing-up"]
        t_s::Real = 5.0, [unit = "s", min = 0, description = "Duration of the swing-up trajectory"]
        catch_tol::Real = 1000.0, [min = 0, description = "Catch region: z' Pc z below this"]
        u_max::Real = 3.0, [unit = "N*m", min = 0, description = "Actuator limit"]
        slew::Real = 300.0, [unit = "N*m/s", min = 0, description = "Actuator slew-rate limit"]
        delay_n::Real = 0.0, [min = 0, max = 10, description = "Actuator delay in samples of 1 ms"]
        quant::Bool = false, [description = "Quantised encoders and difference rates"]
        res_s::Real = 9.587379924285257e-05, [unit = "rad", min = 0, description = "Base encoder resolution"]
        res_q::Real = 9.587379924285257e-05, [unit = "rad", min = 0, description = "Joint encoder resolution"]
        tau_f::Real = 0.005, [unit = "s", min = 0, description = "Rate filter time constant (quantised mode)"]
        balance_only::Bool = false, [description = "Start in the balance phase (no swing-up)"]
    end
    @variables begin
        latched::Real = 0.0, [description = "1 once the balance controller has taken over"]
        ulast::Real = 0.0, [description = "Last slew-limited output"]
        started::Real = 0.0, [description = "1 after the first tick"]
        d1::Real = 0.0
        d2::Real = 0.0
        d3::Real = 0.0
        d4::Real = 0.0
        d5::Real = 0.0
        d6::Real = 0.0
        d7::Real = 0.0
        d8::Real = 0.0
        d9::Real = 0.0
        d10::Real = 0.0
        pp1::Real = 0.0
        wf1::Real = 0.0
        pp2::Real = 0.0
        wf2::Real = 0.0
        pp3::Real = 0.0
        wf3::Real = 0.0
        pp4::Real = 0.0
        wf4::Real = 0.0
        pp5::Real = 0.0
        wf5::Real = 0.0
    end
    @discrete Ts = 1e-3 begin
        r1 = q1
        r2 = q2
        r3 = q3
        r4 = q4
        m0 = s
        m1 = r1
        m2 = r2
        m3 = r3
        m4 = r4
        if quant
            m0 = res_s * round(s / res_s)
            m1 = res_q * round(r1 / res_q)
            m2 = res_q * round(r2 / res_q)
            m3 = res_q * round(r3 / res_q)
            m4 = res_q * round(r4 / res_q)
        end
        p1 = m1
        p2 = p1 + m2
        p3 = p2 + m3
        p4 = p3 + m4
        v0 = sd
        v1 = wq1
        v2 = v1 + wq2
        v3 = v2 + wq3
        v4 = v3 + wq4
        af = 0.001 / (0.001 + tau_f)
        wf1 = ifelse(started > 0.5, wf1 + af * ((m0 - pp1) / 0.001 - wf1), 0.0)
        pp1 = m0
        wf2 = ifelse(started > 0.5, wf2 + af * ((p1 - pp2) / 0.001 - wf2), 0.0)
        pp2 = p1
        wf3 = ifelse(started > 0.5, wf3 + af * ((p2 - pp3) / 0.001 - wf3), 0.0)
        pp3 = p2
        wf4 = ifelse(started > 0.5, wf4 + af * ((p3 - pp4) / 0.001 - wf4), 0.0)
        pp4 = p3
        wf5 = ifelse(started > 0.5, wf5 + af * ((p4 - pp5) / 0.001 - wf5), 0.0)
        pp5 = p4
        started = 1.0
        if quant
            v0 = wf1
            v1 = wf2
            v2 = wf3
            v3 = wf4
            v4 = wf5
        end
        tau = tm - t_on
        utv = ff - (Ks[1] * (m0 - xs[1]) + Ks[2] * (p1 - xs[2]) + Ks[3] * (p2 - xs[3]) + Ks[4] * (p3 - xs[4]) + Ks[5] * (p4 - xs[5]) + Ks[6] * (v0 - xs[6]) + Ks[7] * (v1 - xs[7]) + Ks[8] * (v2 - xs[8]) + Ks[9] * (v3 - xs[9]) + Ks[10] * (v4 - xs[10]))
        ulq = -(Klqr[1] * m0 + Klqr[2] * p1 + Klqr[3] * p2 + Klqr[4] * p3 + Klqr[5] * p4 + Klqr[6] * v0 + Klqr[7] * v1 + Klqr[8] * v2 + Klqr[9] * v3 + Klqr[10] * v4)
        en = Pc[1, 1] * m0 * m0 + 2.0 * Pc[1, 2] * m0 * p1 + 2.0 * Pc[1, 3] * m0 * p2 + 2.0 * Pc[1, 4] * m0 * p3 + 2.0 * Pc[1, 5] * m0 * p4 + 2.0 * Pc[1, 6] * m0 * v0 + 2.0 * Pc[1, 7] * m0 * v1 + 2.0 * Pc[1, 8] * m0 * v2 + 2.0 * Pc[1, 9] * m0 * v3 + 2.0 * Pc[1, 10] * m0 * v4 + Pc[2, 2] * p1 * p1 + 2.0 * Pc[2, 3] * p1 * p2 + 2.0 * Pc[2, 4] * p1 * p3 + 2.0 * Pc[2, 5] * p1 * p4 + 2.0 * Pc[2, 6] * p1 * v0 + 2.0 * Pc[2, 7] * p1 * v1 + 2.0 * Pc[2, 8] * p1 * v2 + 2.0 * Pc[2, 9] * p1 * v3 + 2.0 * Pc[2, 10] * p1 * v4 + Pc[3, 3] * p2 * p2 + 2.0 * Pc[3, 4] * p2 * p3 + 2.0 * Pc[3, 5] * p2 * p4 + 2.0 * Pc[3, 6] * p2 * v0 + 2.0 * Pc[3, 7] * p2 * v1 + 2.0 * Pc[3, 8] * p2 * v2 + 2.0 * Pc[3, 9] * p2 * v3 + 2.0 * Pc[3, 10] * p2 * v4 + Pc[4, 4] * p3 * p3 + 2.0 * Pc[4, 5] * p3 * p4 + 2.0 * Pc[4, 6] * p3 * v0 + 2.0 * Pc[4, 7] * p3 * v1 + 2.0 * Pc[4, 8] * p3 * v2 + 2.0 * Pc[4, 9] * p3 * v3 + 2.0 * Pc[4, 10] * p3 * v4 + Pc[5, 5] * p4 * p4 + 2.0 * Pc[5, 6] * p4 * v0 + 2.0 * Pc[5, 7] * p4 * v1 + 2.0 * Pc[5, 8] * p4 * v2 + 2.0 * Pc[5, 9] * p4 * v3 + 2.0 * Pc[5, 10] * p4 * v4 + Pc[6, 6] * v0 * v0 + 2.0 * Pc[6, 7] * v0 * v1 + 2.0 * Pc[6, 8] * v0 * v2 + 2.0 * Pc[6, 9] * v0 * v3 + 2.0 * Pc[6, 10] * v0 * v4 + Pc[7, 7] * v1 * v1 + 2.0 * Pc[7, 8] * v1 * v2 + 2.0 * Pc[7, 9] * v1 * v3 + 2.0 * Pc[7, 10] * v1 * v4 + Pc[8, 8] * v2 * v2 + 2.0 * Pc[8, 9] * v2 * v3 + 2.0 * Pc[8, 10] * v2 * v4 + Pc[9, 9] * v3 * v3 + 2.0 * Pc[9, 10] * v3 * v4 + Pc[10, 10] * v4 * v4
        lat = ifelse(balance_only, 1.0, ifelse(latched > 0.5 || (tm >= t_on && tau >= t_s - 0.5 && en < catch_tol), 1.0, 0.0))
        latched = lat
        cmd = clamp(ifelse(lat > 0.5, ulq, ifelse(tm < t_on, 0.0, utv)), -u_max, u_max)
        du = slew * 0.001
        out = clamp(cmd, ulast - du, ulast + du)
        ulast = out
        d10 = d9
        d9 = d8
        d8 = d7
        d7 = d6
        d6 = d5
        d5 = d4
        d4 = d3
        d3 = d2
        d2 = d1
        d1 = out
        u = ifelse(delay_n < 0.5, out, ifelse(abs(delay_n - 1.0) < 0.5, d2, 0.0) + ifelse(abs(delay_n - 2.0) < 0.5, d3, 0.0) + ifelse(abs(delay_n - 3.0) < 0.5, d4, 0.0) + ifelse(abs(delay_n - 4.0) < 0.5, d5, 0.0) + ifelse(abs(delay_n - 5.0) < 0.5, d6, 0.0) + ifelse(abs(delay_n - 6.0) < 0.5, d7, 0.0) + ifelse(abs(delay_n - 7.0) < 0.5, d8, 0.0) + ifelse(abs(delay_n - 8.0) < 0.5, d9, 0.0) + ifelse(abs(delay_n - 9.0) < 0.5, d10, 0.0))
        ucmd = cmd
        phase = ifelse(lat > 0.5, 2.0, ifelse(tm < t_on, 0.0, 1.0))
        swinging = ifelse(phase > 0.5 && phase < 1.5, 1.0, 0.0)
        balancing = ifelse(phase > 1.5, 1.0, 0.0)
        vcost = en
    end
end
